import logo from './logo.svg';
import './App.css';
import {useState} from "react";

function App() {
    const [user, setUser] = useState({
        "id" : "",
        "name" : "",
        "pw" : ""
    });

    const handleUserInfoChange= (e) => {
        setUser({
            ...user,
            [e.target.name] : e.target.value
        });
    }
    const signIn = () => {
    }

    return (
        <div className="App">
            <h1>MAIN</h1>
            <br/><br/><br/>
            <div style={{display: 'flex', justifyContent: 'center'}}>
                <div style={{width: '30%', textAlign: 'center'}}>
                    <h3>Sign up</h3>
                    Name: <input type={"text"} name={"name"} onChange={handleUserInfoChange}/><br/>
                    ID: <input type={"text"} name={"id"} onChange={handleUserInfoChange}/><br/>
                    PW: <input type={"text"} name={"pw"} onChange={handleUserInfoChange}/><br/><br/>
                    <button>submit</button>
                </div>
                <div style={{width: '30%', textAlign: 'center'}}>
                    <h3>Sign in</h3>
                    ID: <input type={"text"} onChange={handleUserInfoChange}/><br/>
                    PW: <input type={"text"} onChange={handleUserInfoChange}/><br/><br/>
                    <button>submit</button>
                </div>
            </div>
        </div>
    );
}

export default App;
